BEGIN;UPDATE backend_core.settlement_rollout SET enabled=false WHERE enabled;UPDATE backend_core.original_tax_capture_bindings SET enabled=false WHERE enabled;DO $$DECLARE r record;BEGIN FOR r IN SELECT DISTINCT pg_get_userbyid(a.grantee) role FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid='public.post_bound_financial_v1(uuid,uuid,text,integer,text,jsonb,jsonb,uuid,jsonb)'::regprocedure AND a.grantee<>0 AND a.grantee<>p.proowner LOOP EXECUTE format('REVOKE ALL ON FUNCTION public.post_bound_financial_v1(uuid,uuid,text,integer,text,jsonb,jsonb,uuid,jsonb) FROM %I',r.role);END LOOP;END$$;REVOKE ALL ON FUNCTION public.post_bound_financial_v1(uuid,uuid,text,integer,text,jsonb,jsonb,uuid,jsonb) FROM PUBLIC;COMMIT;
